import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color, DoubleSide } = ctx.THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const group = new Group();
  group.name = 'hub-pricing-card-2-label';

  // Atlas region aspect 512:320 = 1.6
  const planeW = 2.2;
  const planeH = planeW / (512 / 320);
  const geo = new PlaneGeometry(planeW, planeH);

  const mat = new MeshBasicNodeMaterial({
    transparent: true,
    side: DoubleSide,
    color: new Color(colors.surface),
    opacity: 0.92,
  });

  const plane = new Mesh(geo, mat);
  plane.position.set(0, 0, -0.02);
  group.add(plane);

  // Load ceramic grain texture (async, cached) and apply via .map
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    tex.colorSpace = ctx.THREE.SRGBColorSpace;
    mat.map = tex;
    mat.needsUpdate = true;
  }).catch(() => {});

  // Text content — render via fontAtlas
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textStrings = textItems.map((t) => (typeof t === 'string' ? t : t.text)).filter(Boolean);
  const label = textStrings.length ? textStrings.join(' ') : '';

  let textObj = null;
  if (label) {
    textObj = ctx.fontAtlas.createText(label, {
      fontSize: 39,
      color: colors.paper,
      align: 'center',
      letterSpacingPx: 1.2,
    });
    textObj.position.set(0, 0, 0.01);
    group.add(textObj);
  }

  // Press-down / settle subtle entrance: rise-in 0.4 -> 0
  group.position.set(0, 0.4, 0);
  group.scale.setScalar(0.96);

  const tl = gsap.timeline();
  tl.to(group.position, { y: 0, duration: 0.7, ease: 'power3.out' }, 0)
    .to(group.scale, { x: 1, y: 1, z: 1, duration: 0.5, ease: 'power3.out' }, 0)
    .to(group.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.35, ease: 'power2.out' }, 0.5)
    .to(group.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.55, ease: 'power4.out' }, 0.85);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    tl.kill();
    geo.dispose();
    mat.dispose();
    if (textObj && textObj.traverse) {
      textObj.traverse((o) => {
        if (o.geometry) o.geometry.dispose();
        if (o.material) {
          if (Array.isArray(o.material)) o.material.forEach((m) => m.dispose());
          else o.material.dispose();
        }
      });
    }
  };

  return group;
}
